var params = $input.first().json;

var runId = params.run_id;
var templateRef = params.template_ref;
var userId = params.user_id;
var startStep = params.start_from_step || 1;
var title = params.title || templateRef;
var description = params.description || '';
var pdfPath = params.pdf_storage_path || '';
var supabaseUrl = params.SUPABASE_URL || 'https://egrzvwnjrtpwwmqzimff.supabase.co';
var bucket = params.SUPABASE_BUCKET || 'panicleDevelop_1';
var config = params.config || {};

if (!templateRef) {
  throw new Error('Missing required field: template_ref');
}
if (!userId) {
  throw new Error('Missing required field: user_id');
}
var uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(userId)) {
  throw new Error('Invalid user_id format: "' + userId + '". Expected UUID.');
}
if (startStep === 1 && !pdfPath) {
  throw new Error('Missing pdf_storage_path. Upload the PDF to Supabase first, then provide the path.');
}
if (startStep < 1 || startStep > 6) {
  throw new Error('start_from_step must be 1-6. Got: ' + startStep);
}

return [{
  json: {
    run_id: runId,
    template_ref: templateRef,
    user_id: userId,
    start_from_step: startStep,
    title: title,
    description: description,
    pdf_storage_path: pdfPath,
    SUPABASE_URL: supabaseUrl,
    SUPABASE_BUCKET: bucket,
    config: config
  }
}];

var params = $('Validate Params').first().json;
var stateResult = $input.first().json;
var state = Array.isArray(stateResult) ? stateResult[0] : stateResult;

var stepsCompleted = state.steps_completed || [];
var currentStep = state.current_step || params.start_from_step || 1;

return [{
  json: {
    run_id: params.run_id,
    template_ref: params.template_ref,
    user_id: params.user_id,
    title: params.title,
    description: params.description,
    pdf_storage_path: params.pdf_storage_path,
    SUPABASE_URL: params.SUPABASE_URL,
    SUPABASE_BUCKET: params.SUPABASE_BUCKET,
    config: params.config,
    current_step: currentStep,
    steps_completed: stepsCompleted,
    path: state.path || 'undecided',
    step_results: state.step_results || {}
  }
}];

var state = $input.first().json;
var stepsCompleted = state.steps_completed || [];

if (stepsCompleted.indexOf(1) >= 0) {
  return [{ json: Object.assign({}, state, { _skip: true, _msg: 'Step 1 already completed — skipping to step 2' }) }];
}

return [{ json: Object.assign({}, state, { _skip: false }) }];

var state = $('Check Step 1').first().json;
var result = $input.first().json;

var isError = false;
var errorMsg = '';
if (result.statusCode && result.statusCode >= 400) {
  isError = true;
  errorMsg = result.message || JSON.stringify(result);
} else if (result.status === 'error') {
  isError = true;
  errorMsg = result.message || 'Unknown error in Add Form Template';
}

var stepResult = {
  status: isError ? 'error' : 'success',
  auto_mapped: result.auto_mapped_count || result.mapped_count || 0,
  unmapped: result.unmapped_count || 0,
  total_fields: result.total_fields || result.field_count || 0,
  error: errorMsg
};

return [{
  json: Object.assign({}, state, {
    step1_result: stepResult,
    step1_error: isError,
    step1_error_msg: errorMsg
  })
}];

var state = $input.first().json;
return [{
  json: {
    status: 'failed',
    failed_at_step: 1,
    step_name: 'Add Form Template',
    error: state.step1_error_msg,
    run_id: state.run_id,
    template_ref: state.template_ref,
    recovery: 'Fix the issue and re-run with start_from_step=1'
  }
}];

var formData = $input.first().json;
var state = $('Check Step 1').first().json;

var pathChoice = (formData['Path Choice'] || '').toLowerCase();
var path = 'path_b';
if (pathChoice.indexOf('path_a') >= 0) {
  path = 'path_a';
}

var nextStep = (path === 'path_a') ? 2 : 2;

return [{
  json: Object.assign({}, state, {
    path: path,
    current_step: 2,
    steps_completed: (state.steps_completed || []).concat([1])
  })
}];

var state = $('Process Step 1 Resume').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 2,
      step_name: 'Allocate Form Mapping',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      template_ref: state.template_ref,
      recovery: 'Fix the issue and re-run with start_from_step=2'
    }
  }];
}

var nextStep = (state.path === 'path_a') ? 'step3a' : 'step3b';

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([2]),
    step2_result: { status: 'success', overrides: result.overrides_applied || 0 },
    _next: nextStep
  })
}];

var state = $('Check Step 2 Result').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 3,
      step_name: 'Update Extended Data (Path A)',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      recovery: 'Fix the issue and re-run with start_from_step=3'
    }
  }];
}

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([3]),
    current_step: 6,
    step3a_result: { status: 'success', keys_updated: result.keys_count || 0 }
  })
}];

var state = $('Check Step 2 Result').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 3,
      step_name: 'Analyse Form Gaps (Path B)',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      recovery: 'Fix the issue and re-run with start_from_step=3'
    }
  }];
}

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([3]),
    step3b_result: { status: 'success', unmapped: result.overall ? result.overall.total_unmapped : 0, suggestions: result.overall ? result.overall.total_suggestions_found : 0, excel_path: result.excel_path || '' }
  })
}];

var formData = $input.first().json;
var state = $('Check Step 3b Result').first().json;

var confirmation = formData['Confirmation'] || '';
if (confirmation.toLowerCase().indexOf('abort') >= 0) {
  return [{
    json: {
      status: 'aborted',
      aborted_at_step: 3,
      run_id: state.run_id,
      template_ref: state.template_ref,
      message: 'Pipeline aborted by user after gap analysis.'
    }
  }];
}

return [{
  json: Object.assign({}, state, {
    current_step: 4
  })
}];

var state = $('Process Step 3b Resume').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 4,
      step_name: 'Generate Synthetic Data',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      recovery: 'Fix the issue and re-run with start_from_step=4'
    }
  }];
}

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([4]),
    current_step: 5,
    step4_result: { status: 'success', fields_created: result.fields_created || 0, synthetic_keys: result.synthetic_data_keys || [] }
  })
}];

var state = $('Check Step 4 Result').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 5,
      step_name: 'Generate Realistic Data',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      recovery: 'Fix the issue and re-run with start_from_step=5. Ensure config.openai_api_key is set.'
    }
  }];
}

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([5]),
    current_step: 6,
    step5_result: { status: result.status || 'success', fields_updated: result.fields_updated || 0 }
  })
}];

var result = $input.first().json;
var runId = '';
var templateRef = '';
var path = '';

// Determine which path we came from
try { runId = $('Validate Params').first().json.run_id; } catch(e) {}
try { templateRef = $('Validate Params').first().json.template_ref; } catch(e) {}

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 6,
      step_name: 'Fill Form',
      error: result.message || JSON.stringify(result),
      run_id: runId,
      template_ref: templateRef,
      recovery: 'Fix the issue and re-run with start_from_step=6'
    }
  }];
}

var fillResult = {
  status: result.status || 'success',
  fields_filled: result.fields_filled || 0,
  fields_missing: result.fields_missing || 0,
  warnings: result.warnings || [],
  final_pdf: result.final_pdf || result.final_pdf_path || ''
};

return [{
  json: {
    status: 'completed',
    run_id: runId,
    template_ref: templateRef,
    fill_result: fillResult
  }
}];

var finalState = $('Check Fill Result').first().json;

if (finalState.status === 'completed') {
  return [{
    json: {
      status: 'completed',
      message: 'Pipeline completed successfully! PDF form has been filled.',
      run_id: finalState.run_id,
      template_ref: finalState.template_ref,
      fields_filled: finalState.fill_result.fields_filled,
      fields_missing: finalState.fill_result.fields_missing,
      final_pdf: finalState.fill_result.final_pdf,
      warnings: finalState.fill_result.warnings
    }
  }];
}

return [{ json: finalState }];

var state = $input.first().json;
var step = state.current_step || 2;

// For resume paths that skip directly to a step
return [{
  json: Object.assign({}, state, {
    _skip: true,
    _msg: 'Skipping to step ' + step + ' (steps already completed)'
  })
}];

var state = $('Resume at Step 2').first().json;
var result = $input.first().json;

var isError = (result.statusCode && result.statusCode >= 400) || result.status === 'error';
if (isError) {
  return [{
    json: {
      status: 'failed',
      failed_at_step: 2,
      step_name: 'Allocate Form Mapping',
      error: result.message || JSON.stringify(result),
      run_id: state.run_id,
      recovery: 'Fix the issue and re-run with start_from_step=2'
    }
  }];
}

var nextStep = (state.path === 'path_a') ? 'step3a' : 'step3b';

return [{
  json: Object.assign({}, state, {
    steps_completed: (state.steps_completed || []).concat([2]),
    step2_result: { status: 'success' },
    _next: nextStep
  })
}];

// Steps 3-5 direct resume entry point
var state = $input.first().json;
var step = state.current_step;

return [{ json: state }];

var state = $('Check Step 4 Result').first().json;

// Get current system_config fields
var configResult = $('Fetch System Config').first().json;
var configRow = Array.isArray(configResult) ? configResult[0] : configResult;
var currentFields = (configRow && configRow.setting && configRow.setting.fields) || [];

// Build set of registered keys
var registeredKeys = {};
for (var i = 0; i < currentFields.length; i++) {
  registeredKeys[currentFields[i].key] = true;
}

// Get actual user_details keys
var udResult = $('Fetch User Details').first().json;
var udRow = Array.isArray(udResult) ? udResult[0] : udResult;
var details = (udRow && udRow.details) || {};
var detailKeys = Object.keys(details);

// Find new keys not in system_config
var newFields = [];
for (var k = 0; k < detailKeys.length; k++) {
  var key = detailKeys[k];
  if (!registeredKeys[key] && key !== '' && key.match(/^[a-z][a-z0-9_]*$/)) {
    var label = key.replace(/_/g, ' ');
    label = label.replace(/\b\w/g, function(c) { return c.toUpperCase(); });
    newFields.push({
      key: key,
      label: label,
      type: 'text',
      required: false,
      source: 'user_details'
    });
  }
}

if (newFields.length === 0) {
  return [{ json: Object.assign({}, state, { sync_result: { status: 'no_change', new_keys: 0 } }) }];
}

// Append new fields to existing array
var updatedFields = currentFields.concat(newFields);
var newKeyNames = newFields.map(function(f) { return f.key; });

return [{
  json: Object.assign({}, state, {
    _sync_needed: true,
    _updated_setting: { fields: updatedFields },
    sync_result: { status: 'synced', new_keys: newFields.length, keys_added: newKeyNames }
  })
}];
